<?php
namespace App\Services;
use App\Models\OrderModel;
class OrderStatusService
{private array $flows=['pending'=>['confirmed','cancelled'],'confirmed'=>['processing','cancelled'],'processing'=>['shipped','cancelled'],'shipped'=>['delivered'],'delivered'=>[],'cancelled'=>[]];public function can(string $from,string $to):bool{return in_array($to,$this->flows[$from]??[],true);}public function options(string $from):array{return $this->flows[$from]??[];}public function transition(int $id,string $to,?string $note=null):void{$db=db_connect();$db->transException(true)->transStart();$order=$db->query('SELECT * FROM '.$db->prefixTable('orders').' WHERE id=? FOR UPDATE',[$id])->getRowArray();if(!$order||!$this->can($order['order_status'],$to))throw new \RuntimeException('This status transition is not allowed.');if($to==='shipped'&&!$db->table('shipments')->where('order_id',$id)->whereIn('status',['booked','picked_up','in_transit','delivered'])->get()->getRowArray())throw new \RuntimeException('Book a shipment before marking the order shipped.');if($to==='cancelled'&&!$order['inventory_restored_at'])$this->restore($db,$order);$now=date('Y-m-d H:i:s');if($to==='cancelled'){$shipment=$db->table('shipments')->where('order_id',$id)->whereIn('status',['prepared','booked'])->get()->getRowArray();if($shipment){$db->table('shipments')->where('id',$shipment['id'])->update(['status'=>'cancelled','updated_at'=>$now]);$db->table('shipment_events')->insert(['shipment_id'=>$shipment['id'],'from_status'=>$shipment['status'],'to_status'=>'cancelled','tracking_note'=>'Order cancelled; cancel merchant-panel booking if needed','source'=>'admin','changed_by_admin_id'=>session('admin_id')?:null,'created_at'=>$now]);}}$db->table('orders')->where('id',$id)->update(['order_status'=>$to,'updated_at'=>$now]);$db->table('order_status_history')->insert(['order_id'=>$id,'from_status'=>$order['order_status'],'to_status'=>$to,'note'=>trim((string)$note)?:null,'changed_by_admin_id'=>session('admin_id'),'created_at'=>$now]);$db->transComplete();try{(new SmsService())->trigger($id,$to);}catch(\Throwable $e){log_message('error','Order status SMS enqueue failed: {error}',['error'=>$e->getMessage()]);}}
 private function restore($db,array $order):void{$items=$db->table('order_items')->where('order_id',$order['id'])->get()->getResultArray();$now=date('Y-m-d H:i:s');foreach($items as $item){if($item['item_type']==='package'){$parts=$db->table('order_item_components')->where(['order_item_id'=>$item['id'],'stock_deducted'=>1])->get()->getResultArray();foreach($parts as $part)$this->add($db,$part['variant_id']?'product_variants':'products',(int)($part['variant_id']?:$part['product_id']),(int)$part['total_quantity'],(int)$part['product_id'],$part['variant_id']?(int)$part['variant_id']:null,(int)$order['id'],$now);}elseif((int)$item['stock_deducted']===1)$this->add($db,$item['variant_id']?'product_variants':'products',(int)($item['variant_id']?:$item['product_id']),(int)$item['quantity'],(int)$item['product_id'],$item['variant_id']?(int)$item['variant_id']:null,(int)$order['id'],$now);}$db->table('orders')->where('id',$order['id'])->update(['inventory_restored_at'=>$now]);}
 private function add($db,string $table,int $id,int $q,int $pid,?int $vid,int $oid,string $now):void{(new InventoryService())->moveOrderStock($db,$table,$id,$q,$pid,$vid,'order_cancel_restore','order',$oid,'Cancelled order stock restoration',session('admin_id')?:null);}}
